<script setup>
import {ref,onMounted} from 'vue';import {supabase} from '../lib/supabase.js'
const form=ref({site_name:'',subtitle:'',announcement:'',contact_email:'',footer_text:''}),loading=ref(true),saving=ref(false),message=ref('')
onMounted(async()=>{const {data,error}=await supabase.from('site_settings').select('*').eq('id',true).single();if(error)message.value=error.message;else Object.assign(form.value,data);loading.value=false})
async function save(){saving.value=true;message.value='';const f=form.value;const {data,error}=await supabase.rpc('update_site_settings',{p_site_name:f.site_name,p_subtitle:f.subtitle,p_announcement:f.announcement,p_contact_email:f.contact_email,p_footer_text:f.footer_text});saving.value=false;if(error)message.value=error.message;else{Object.assign(form.value,data);message.value='设置已保存'}}
</script>
<template><div class="page"><div class="page-head"><div><h2>站点设置</h2><p>只接受纯文本字段，不允许注入任意 HTML。</p></div></div><div v-if="message" class="notice" :style="message.includes('已保存')?'background:#eaf5eb;color:#28643a':''">{{message}}</div><form v-if="!loading" class="card" style="max-width:780px" @submit.prevent="save"><div class="field"><label>站点名称</label><input v-model="form.site_name" maxlength="80" required></div><div class="field"><label>副标题</label><input v-model="form.subtitle" maxlength="160"></div><div class="field"><label>全站公告</label><textarea v-model="form.announcement" maxlength="500"></textarea></div><div class="field"><label>联系邮箱</label><input v-model="form.contact_email" type="email" maxlength="200"></div><div class="field"><label>页脚文案</label><textarea v-model="form.footer_text" maxlength="300"></textarea></div><button class="btn" :disabled="saving">{{saving?'保存中…':'保存设置'}}</button></form><div v-else class="loading">正在读取设置…</div></div></template>
